	dat_inicio_toc timestamp without time zone NOT NULL,
	dat_fim_toc timestamp without time zone,
	CONSTRAINT tipo_ocorrencia_pkey PRIMARY KEY (id_tipo_ocorrencia_toc)
);

CREATE TABLE cad.tb_subtipo_ocorrencia_soc (
